import  org.apache.commons.csv.CSVFormat;
 import  org.apache.commons.csv.CSVPrinter;
 import  org.junit.jupiter.api.Test;

 import  java.io.ByteArrayOutputStream;
 import  java.io.IOException;
 import  java.io.PrintWriter;

 public   class  CommonsCsvTest {

   @Test
    void testWithParStream()  throws  IOException {
        ByteArrayOutputStream baos =  new  ByteArrayOutputStream();
         try (CSVPrinter printer =  new  CSVPrinter( new  PrintWriter(baos), CSVFormat.DEFAULT)){
            printer.printRecord(java.util.stream.Stream.of( "col a" ,  "col b" ,  "col c" ).parallel());
        }
    }

    @Test
    void testWithSeqStream()  throws  IOException {
        ByteArrayOutputStream baos =  new  ByteArrayOutputStream();
         try (CSVPrinter printer =  new  CSVPrinter( new  PrintWriter(baos), CSVFormat.DEFAULT)){
            printer.printRecord(java.util.stream.Stream.of( "col a" ,  "col b" ,  "col c" ));
        }
    }

}


 A simple workaround is to call sequential() on any passed in Stream. 

 I don't know why this is happening.  At first I thought it must be a problem with the underlying Stream implementation but this code has no problem: 

   


@Test
void testJavaStream(){
    java.util.stream.Stream.of( "col a" ,  "col b" ,  "col c" ).parallel()
            .forEachOrdered( System .out::println);
}

